import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;

public class ReportExportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Template for generating CSV export filenames
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z0-9_]{1,64}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String reportId = req.getParameter("report_id");
        String format = req.getParameter("format");
        String columns = req.getParameter("columns");

        if (reportId == null || !SAFE_IDENTIFIER.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report_id");
            return;
        }

        if (format == null) format = "csv";

        // columns parameter allows selecting which columns to export
        // Expected format: "col1,col2,col3"
        String[] requestedColumns;
        if (columns != null && !columns.isEmpty()) {
            requestedColumns = columns.split(",");
            // Validate each column name
            for (String col : requestedColumns) {
                if (!SAFE_IDENTIFIER.matcher(col.trim()).matches()) {
                    resp.sendError(400, "Invalid column name: " + col);
                    return;
                }
            }
        } else {
            requestedColumns = new String[]{"id", "name", "value", "created_at"};
        }

        String columnList = String.join(", ", requestedColumns);

        // Build query - reportId is validated, columns are validated
        String query = "SELECT " + columnList + " FROM report_" + reportId;

        // Apply optional date filter
        String dateFrom = req.getParameter("date_from");
        String dateTo = req.getParameter("date_to");

        if (dateFrom != null || dateTo != null) {
            query += " WHERE 1=1";
            if (dateFrom != null) {
                // Validate ISO date format
                if (!dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
                    resp.sendError(400, "Invalid date_from format");
                    return;
                }
                query += " AND created_at >= '" + dateFrom + "'";
            }
            if (dateTo != null) {
                if (!dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
                    resp.sendError(400, "Invalid date_to format");
                    return;
                }
                query += " AND created_at <= '" + dateTo + "'";
            }
        }

        // Apply sort parameter
        String sortBy = req.getParameter("sort");
        String sortDir = req.getParameter("dir");
        if (sortBy != null) {
            if (!SAFE_IDENTIFIER.matcher(sortBy).matches()) {
                resp.sendError(400, "Invalid sort column");
                return;
            }
            query += " ORDER BY " + sortBy;
            if ("desc".equalsIgnoreCase(sortDir)) {
                query += " DESC";
            }
        }

        // Apply limit - this is where the template substitution happens
        String limitTemplate = req.getParameter("limit_expr");
        if (limitTemplate != null) {
            Map<String, String> valuesMap = new HashMap<>();
            valuesMap.put("page_size", req.getParameter("page_size") != null ? req.getParameter("page_size") : "100");
            valuesMap.put("page", req.getParameter("page") != null ? req.getParameter("page") : "0");
            StringSubstitutor sub = new StringSubstitutor(valuesMap);
            String limitClause = sub.replace(limitTemplate);
            query += " LIMIT " + limitClause;
        } else {
            query += " LIMIT 1000";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition", "attachment; filename=report_" + reportId + ".csv");
            PrintWriter out = resp.getWriter();

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            for (int i = 1; i <= colCount; i++) {
                if (i > 1) out.print(",");
                out.print(meta.getColumnName(i));
            }
            out.println();

            while (rs.next()) {
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(",");
                    String val = rs.getString(i);
                    if (val != null) {
                        out.print("\"" + val.replace("\"", "\"\"") + "\"");
                    }
                }
                out.println();
            }
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
